//! The curves are precomputed by `oc-device` ([`oc_device::response`]: the stock graph walked in small signal,
//! validated against `re/dsp/stock_sim.py`) from a stock U7001 backup, and embedded as [`DATA`]
//! (`bose_curves.bin`, regenerated by the test in [`tests`]). Reference conditions: master volume −20 dB,
//! loudness at its small-signal boost (or off), decorrelated stereo, on the graph's [`FREQS`].
//!
//! `bose_curves.bin`, little-endian: `"OCRC"`, version u16 = 1, points u16, sets u8 = 2 (loudness off, on),
//! curves u8 = 6 (main satellite path, inner L, inner R, outer L, outer R, bass), 2 reserved bytes, then
//! `sets × curves × points` f32 (dB).

#[cfg(test)]
mod tests;

use std::sync::LazyLock;

#[cfg(doc)]
use super::biquad::FREQS;
use super::biquad::POINTS;
use super::eq::Target;

pub const DATA: &[u8] = include_bytes!("bose_curves.bin");
const MAGIC: &[u8; 4] = b"OCRC";
const VERSION: u16 = 1;
const HEADER: usize = 12;
const SETS: usize = 2;
const CURVES: usize = 6;

/// The Bose base's curves on [`FREQS`] (dB) for one loudness setting.
#[derive(Debug, Clone, PartialEq)]
pub struct Curves {
    /// The main satellite path (the left satellite's two drivers, power average).
    pub main: [f64; POINTS],
    pub outputs: [[f64; POINTS]; 5],
}

impl Curves {
    pub fn of(&self, t: Target) -> &[f64; POINTS] {
        match t {
            Target::Global => &self.main,
            t => &self.outputs[t.index() - 1],
        }
    }
}

pub(crate) fn parse(b: &[u8]) -> Option<[Curves; SETS]> {
    let u16_at = |o: usize| u16::from_le_bytes([b[o], b[o + 1]]) as usize;
    if b.len() != HEADER + SETS * CURVES * POINTS * 4 || &b[..4] != MAGIC || u16_at(4) != VERSION as usize {
        return None;
    }
    if u16_at(6) != POINTS || b[8] as usize != SETS || b[9] as usize != CURVES {
        return None;
    }
    let curve = |s: usize, c: usize| -> [f64; POINTS] {
        std::array::from_fn(|i| {
            let o = HEADER + ((s * CURVES + c) * POINTS + i) * 4;
            f64::from(f32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]))
        })
    };
    Some(std::array::from_fn(|s| Curves { main: curve(s, 0), outputs: std::array::from_fn(|o| curve(s, o + 1)) }))
}

/// Writes a curves file (`sets[0]` loudness off, `sets[1]` on): the generator, in the tests.
#[cfg(test)]
pub(crate) fn encode(sets: &[Curves; SETS]) -> Vec<u8> {
    let mut v = Vec::with_capacity(HEADER + SETS * CURVES * POINTS * 4);
    v.extend_from_slice(MAGIC);
    v.extend_from_slice(&VERSION.to_le_bytes());
    v.extend_from_slice(&(POINTS as u16).to_le_bytes());
    v.extend_from_slice(&[SETS as u8, CURVES as u8, 0, 0]);
    for c in sets {
        for curve in std::iter::once(&c.main).chain(c.outputs.iter()) {
            for x in curve {
                v.extend_from_slice(&(*x as f32).to_le_bytes());
            }
        }
    }
    v
}

static EMBEDDED: LazyLock<[Curves; SETS]> = LazyLock::new(|| parse(DATA).expect("bose_curves.bin matches the graph's points (regenerate it)"));

pub fn curves(loudness: bool) -> &'static Curves {
    &EMBEDDED[usize::from(loudness)]
}
